<?php
require_once __DIR__ . '/scholarship_config_versions.php';
freezeUnversionedApplications($pdo, (int) $scholarship['ScholarshipID'], (int) $_SESSION['user_id']);
$stmt=$pdo->prepare('SELECT cv.*, CONCAT(COALESCE(u.FirstName,\'\'), \' \', COALESCE(u.LastName,\'\')) CreatorName, (SELECT COUNT(*) FROM application a WHERE a.ConfigurationVersionID=cv.ConfigurationVersionID) ApplicationCount FROM scholarship_configuration_versions cv LEFT JOIN users u ON u.UserID=cv.CreatedBy WHERE cv.ScholarshipID=? ORDER BY cv.VersionNumber DESC');
$stmt->execute([$scholarship['ScholarshipID']]);$versions=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
